                removed.add((r,c))

    for r,c in removed:
        g[r][c] = bg

    # Complete only the central gap of an upward diagonal crossing a horizontal
    # straight line; this is the sole addition required by the transformation.
    for r in range(1,h):
        for lo in range(w):
            for hi in range(lo+4,w):
                if g[r][lo] == bg or g[r][hi] != g[r][lo]:
                    continue
                color = g[r][lo]
                if not all(g[r][c] == bg for c in range(lo+1,hi)):
                    continue
                if hi-lo-1 > 5:
                    continue
                left_branch = any((r+dr,c) in removed for dr,c in
                                  ((-1,lo+1),(-2,lo+2),(1,lo+1),(2,lo+2)))
                right_branch = any((r+dr,c) in removed for dr,c in
                                   ((-1,hi-1),(-2,hi-2),(1,hi-1),(2,hi-2)))
                if left_branch and right_branch:
                    for c in range(lo+1,hi):
                        g[r][c] = color
    return g
